let smartArea='Process',smartLayer='Business',smartZoom=1,smartPan={x:0,y:0},smartFactoryMode='rendered';
const campusAreas=[{id:'Workforce Mgmt',name:'Workforce',x:26,y:65,desc:'Administration, qualified people and shift readiness.'},{id:'Quality',name:'Quality laboratory',x:17,y:35,desc:'Product acceptance, PAT measurements and cleaning validation.'},{id:'Process',name:'Production',x:46,y:23,desc:'Batch execution, throughput and handover to packaging.'},{id:'Packaging',name:'Packaging',x:72,y:34,desc:'Line performance, output and delivery recovery.'},{id:'Facility',name:'Utilities',x:82,y:14,desc:'Building conditions, energy and reliable factory services.'},{id:'Maintenance',name:'Maintenance',x:76,y:64,desc:'Asset health, planned interventions and business exposure.'}];
function smartAreaData(id){const s=snapshot(),b=scopedBatches(true),jobs=assets.map((a,i)=>jobFor(i)),open=jobs.filter(j=>j.status!=='Completed').length,holds=b.filter(x=>x.status==='Held').length;const values={
'Workforce Mgmt':{state:'Ready',metric:'3',unit:'eligible technicians',detail:'100% shift coverage',target:'Assign jobs only to valid qualifications',action:'Review qualification renewals and task coverage.',trend:[72,81,88,94,97,100]},
'Quality':{state:holds?'Review required':'Within target',metric:s.quality+'%',unit:'first-pass quality',detail:holds+' batches on hold',target:'Target ≥ 98%',action:holds?'Review held batches before the next packaging handover.':'Continue monitoring sample PAT and cleaning results.',trend:[s.quality-.8,s.quality-.5,s.quality-.6,s.quality-.3,s.quality+.1,s.quality]},
'Process':{state:'Operating',metric:state.factory===2?'89.2%':'94.8%',unit:'production attainment',detail:b.filter(x=>x.status!=='Complete').length+' active batches',target:'Target 95%',action:'Prioritize the earliest delivery commitments and clear quality holds.',trend:[-7,-5,-4,-2,-.5,0].map(v=>v+(state.factory===2?89.2:94.8))},
'Packaging':{state:'Changeover',metric:'Line 2',unit:'recovery focus',detail:'3 packaging lines',target:'Protect committed dispatch dates',action:'Review changeover progress and prioritize the affected orders.',trend:[62,67,73,78,84,89]},
'Facility':{state:'Available',metric:'99.4%',unit:'facility availability',detail:'98% controlled areas ready',target:'Target ≥ 99%',action:'Schedule AHU-03 filter inspection before readiness is affected.',trend:[98.8,99,99.2,99,99.3,99.4]},
'Maintenance':{state:open?'Inspection due':'Complete',metric:String(open),unit:'open work orders',detail:'Pump P-104 · '+jobFor(0).status,target:'Plan work around production windows',action:open?'Assign a qualified technician and inspect the condition advisory.':'Scheduled sample inspections have been completed.',trend:[65,70,73,75,77,78]}
};return values[id]}
function chooseSmartArea(id){if(!campusAreas.some(a=>a.id===id))return;smartArea=id;if(smartLayer==='Utilities'&&id!=='Facility')smartLayer='Business';op.located=false;render()}
function chooseSmartLayer(layer){if(!['Business','Attention','Utilities'].includes(layer))return;smartLayer=layer;if(layer==='Utilities')smartArea='Facility';if(layer==='Attention')smartArea='Maintenance';render()}
function smartMiniTrend(values){const lo=Math.min(...values)-1,hi=Math.max(...values)+1,coords=values.map((v,i)=>[4+i*29,39-(v-lo)/(hi-lo)*32]);return `<svg class="smart-mini-trend" viewBox="0 0 154 44" aria-label="Illustrative trend"><path d="${coords.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ')}" fill="none" stroke="#a6f8d6" stroke-width="2"/>${coords.map((p,i)=>`<circle ${vizAttrs('Area performance trend','Sample '+(i+1),values[i],'%')} cx="${p[0]}" cy="${p[1]}" r="3.5" fill="#b6ffe2"/>`).join('')}</svg>`}
function smartFactoryView(){const f=factories[factoryIndex()],s=snapshot(),area=campusAreas.find(a=>a.id===smartArea)||campusAreas[2],d=smartAreaData(area.id),metrics=pageMetrics();return `<div class="smart-factory-heading"><div><small>FACTORY INTELLIGENCE / ${f.city.toUpperCase()}</small><h1>${f.name}</h1><p><span class="dot"></span>Business performance · Site readiness · Operational decisions</p></div><div class="actions">${opButton('← Factory network',"factoryInterior=false;render()")}${opButton('Cameras','cameraCenter()')}${opButton('Weather','weatherCenter()')}</div></div><div class="smart-summary">${metrics.map((m,i)=>`<button data-viz-point="${escapeHTML(JSON.stringify({title:m[0],label:f.name,value:m[1],unit:'',note:m[2]}))}" onclick="go('${i===3?'Supply Chain':i===2?'Quality':'Production Overview'}')"><small>${m[0]}</small><strong>${m[1]}</strong><span>${m[2]}</span></button>`).join('')}</div><div class="smart-factory-layout"><section class="panel smart-campus-panel"><div class="panelhead"><div><h2>Intelligent campus explorer</h2><small>Select a building to inspect business readiness and priority actions</small></div><div class="segmented">${['Business','Attention','Utilities'].map(l=>opButton(l,`chooseSmartLayer('${l}')`,smartLayer===l?'active':'')).join('')}</div></div><div class="smart-view-options"><span><i class="smart-pulse"></i> ILLUSTRATIVE CAMPUS · ${smartFactoryMode==='rendered'?'3D RENDERED VIEW':'ENGINEERING MODEL'}</span><div>${opButton('Rendered campus',"smartFactoryMode='rendered';render()",smartFactoryMode==='rendered'?'active':'')}${opButton('Explore 3D',"smartFactoryMode='engineering';render()",smartFactoryMode==='engineering'?'active':'')}</div></div>${smartFactoryMode==='engineering'?engineeringModelSlot('factory',0,true):`<div class="smart-campus-viewer" id="smart-campus-viewer"><div class="smart-campus-grid"></div><div class="smart-campus-scene" id="smart-campus-scene" style="transform:translate(${smartPan.x}px,${smartPan.y}px) scale(${smartZoom})"><img src="assets/factory-detailed-campus.png" alt="Detailed illustrative 3D campus with production hall, packaging, quality laboratory, utility center, workshop and administration" draggable="false">${campusAreas.map(a=>{const x=smartAreaData(a.id),attention=['Maintenance','Packaging'].includes(a.id)||a.id==='Quality'&&x.state==='Review required';return `<button class="smart-building-hotspot ${a.id===smartArea?'selected':''} ${attention?'needs-attention':''} ${smartLayer==='Attention'&&!attention||smartLayer==='Utilities'&&a.id!=='Facility'?'layer-muted':''}" style="left:${a.x}%;top:${a.y}%" onclick="chooseSmartArea('${a.id}')"><span class="hotspot-number">${campusAreas.indexOf(a)+1}</span><span><strong>${a.name}</strong><small>${smartLayer==='Business'?x.metric+' '+x.unit:x.state}</small></span><i></i></button>`}).join('')}</div><div class="smart-campus-controls">${opButton('−','zoomSmartCampus(-.15)')}${opButton('Reset','resetSmartCampus()')}${opButton('+','zoomSmartCampus(.15)')}${opButton('Enlarge','enlargeSmartCampus()')}</div><div class="smart-campus-caption">Drag to pan · Use + / − to zoom · Select an area for business details</div></div>`}<div class="smart-area-strip">${campusAreas.map(a=>`<button class="${a.id===smartArea?'active':''}" onclick="chooseSmartArea('${a.id}')"><span class="dot" style="${['Maintenance','Packaging'].includes(a.id)?'background:#ffd09d':''}"></span>${a.name}</button>`).join('')}</div></section><aside class="smart-factory-inspector"><section class="panel smart-area-inspector"><div class="row"><small>SELECTED AREA</small><span class="pill ${['Maintenance','Packaging'].includes(area.id)?'amber-pill':''}">${d.state}</span></div><h2>${area.name}</h2><p>${area.desc}</p><div class="smart-area-reading"><strong>${d.metric}</strong><span>${d.unit}</span></div><div class="row"><small>${d.target}</small>${smartMiniTrend(d.trend)}</div><div class="smart-detail-line"><span>Readiness</span><strong>${d.detail}</strong></div>${op.located?`<div class="smart-located">⌖ Located asset: ${assets[op.asset].id} · ${assets[op.asset].name}</div>`:''}<div class="smart-next-action"><small>RECOMMENDED NEXT STEP</small><p>${d.action}</p></div>${opButton('Open '+area.name+' &nbsp; →',`go('${area.id}')`,'smart-open-area')}<div class="actions">${opButton('Related alarms','alarmCenter()')}${opButton('Documents',`documentCenter('${area.id==='Process'?'Process':area.id==='Quality'?'Quality':area.id==='Maintenance'?'Maintenance':'Factory'}')`)}</div></section><section class="panel smart-factory-decisions"><h2>Site decision center</h2><button onclick="op.asset=0;go('Maintenance')"><span class="warning">●</span><span><strong>Protect production uptime</strong><small>Inspect the pump condition advisory</small></span><b>→</b></button><button onclick="state.line=1;go('Packaging')"><span class="warning">●</span><span><strong>Recover packaging output</strong><small>Review Line 2 changeover</small></span><b>→</b></button><button onclick="reportCenter()"><span class="positive">●</span><span><strong>Share the business view</strong><small>Export a scoped performance report</small></span><b>→</b></button></section></aside></div><div class="smart-factory-foot"><span>Illustrative campus layout · Live equipment is not connected</span><span id="storage-status">Demo actions and assignments are stored in this browser</span></div>`}
function zoomSmartCampus(delta){smartZoom=Math.max(.75,Math.min(1.9,smartZoom+delta));const scene=$('#smart-campus-scene');if(scene)scene.style.transform=`translate(${smartPan.x}px,${smartPan.y}px) scale(${smartZoom})`}
function resetSmartCampus(){smartZoom=1;smartPan={x:0,y:0};zoomSmartCampus(0)}
function enlargeSmartCampus(){openModal(factories[factoryIndex()].name+' · Campus view',`<div class="smart-campus-enlarged"><img src="assets/factory-detailed-campus.png" alt="Detailed 3D-rendered pharmaceutical factory campus"></div><div class="actions">${campusAreas.map(a=>opButton(a.name,`$('#modal').close();chooseSmartArea('${a.id}')`)).join('')}</div><p class="note">Illustrative campus rendering; these areas demonstrate navigation and are not an engineering floor plan.</p>`);$('#modal').classList.add('wide-modal','equipment-modal')}
const terrainNetworkBeforeSmart=terrainNetwork;terrainNetwork=function(){return terrainNetworkBeforeSmart().replace('class="terrain-campus" src="assets/factory-campus.png"','class="terrain-campus terrain-campus-3d" src="assets/factory-mini.png"')};
const factoryBeforeSmartCampus=factory;factory=function(){return factoryInterior?smartFactoryView():factoryBeforeSmartCampus()};
function wireCampusPan(){const viewer=$('#smart-campus-viewer');if(!viewer)return;let drag=null;viewer.addEventListener('pointerdown',e=>{if(e.target.closest('button')||e.button!==0)return;drag={x:e.clientX,y:e.clientY,panX:smartPan.x,panY:smartPan.y};viewer.setPointerCapture?.(e.pointerId);viewer.classList.add('panning')});viewer.addEventListener('pointermove',e=>{if(!drag)return;smartPan={x:Math.max(-180,Math.min(180,drag.panX+e.clientX-drag.x)),y:Math.max(-130,Math.min(130,drag.panY+e.clientY-drag.y))};zoomSmartCampus(0)});const stop=()=>{drag=null;viewer.classList.remove('panning')};viewer.addEventListener('pointerup',stop);viewer.addEventListener('pointercancel',stop)}
const renderBeforeSmartCampus=render;render=function(){document.body.classList.toggle('smart-factory-mode',state.tab==='Factory Overview'&&factoryInterior);if(op.located&&op.locationArea)smartArea=op.locationArea;renderBeforeSmartCampus();if(state.tab==='Factory Overview'&&factoryInterior)wireCampusPan()};
render();
